import { describe, expect, test } from "bun:test";
import {
	analyticsPath,
	analyticsUrl,
	sanitizeAnalyticsProperties,
	sanitizePostHogEvent,
} from "../lib/analytics-privacy";

describe("PostHog analytics privacy", () => {
	test("redacts identifiers from private routes", () => {
		expect(analyticsPath("/s/private-share-id")).toBe("/s/:shareId");
		expect(analyticsPath("/courses/join/private-token")).toBe("/courses/join/:token");
		expect(analyticsPath("/courses/course-123/settings")).toBe("/courses/:courseId/settings");
	});

	test("removes query strings and fragments from captured URLs", () => {
		expect(analyticsUrl("https://keating.help/chat?session=secret#turn-2")).toBe(
			"https://keating.help/chat",
		);
		expect(analyticsUrl("/s/private-share-id?from=email")).toBe("/s/:shareId");
	});

	test("drops learning content while retaining behavioral and AI metrics", () => {
		const sanitized = sanitizeAnalyticsProperties({
			prompt_text: "Teach me topology",
			topic: "topology",
			$ai_input: [{ role: "user", content: "private" }],
			$ai_output_choices: [{ role: "assistant", content: "private" }],
			$ai_input_tokens: 42,
			$ai_output_tokens: 17,
			model: "openai/gpt-5",
			duration_ms: 810,
		});

		expect(sanitized.prompt_text).toBeUndefined();
		expect(sanitized.topic).toBeUndefined();
		expect(sanitized.$ai_input).toBeUndefined();
		expect(sanitized.$ai_output_choices).toBeUndefined();
		expect(sanitized.$ai_input_tokens).toBe(42);
		expect(sanitized.$ai_output_tokens).toBe(17);
		expect(sanitized.model).toBe("openai/gpt-5");
	});

	test("sanitizes complete capture payloads without mutating the source", () => {
		const source = {
			uuid: "event-id",
			event: "message_sent",
			properties: {
				prompt_text: "private",
				$current_url: "https://keating.help/chat?session=private",
			},
		} as any;
		const sanitized = sanitizePostHogEvent(source)!;

		expect(sanitized.properties.prompt_text).toBeUndefined();
		expect(sanitized.properties.$current_url).toBe("https://keating.help/chat");
		expect(source.properties.prompt_text).toBe("private");
	});
});

import type { CaptureResult, Properties } from "posthog-js";

/**
 * Custom properties that can contain learner-authored or model-authored data.
 * Keating analytics are deliberately behavioral: content stays on the user's
 * device and with the model provider they selected.
 */
const PRIVATE_CONTENT_PROPERTIES = new Set([
	"args",
	"content",
	"input",
	"message",
	"messages",
	"output",
	"prompt_text",
	"response",
	"result",
	"sample_text",
	"tool_args",
	"tool_result",
	"topic",
	"$ai_input",
	"$ai_output_choices",
]);

const PRIVATE_ROUTE_PATTERNS: ReadonlyArray<[RegExp, string]> = [
	[/^\/s\/[^/]+/, "/s/:shareId"],
	[/^\/courses\/join\/[^/]+/, "/courses/join/:token"],
	[/^\/courses\/[^/]+/, "/courses/:courseId"],
	[/^\/usage\/evolution\/[^/]+/, "/usage/evolution/:evolutionId"],
];

export function analyticsPath(pathname: string): string {
	for (const [pattern, replacement] of PRIVATE_ROUTE_PATTERNS) {
		if (pattern.test(pathname)) return pathname.replace(pattern, replacement);
	}
	return pathname;
}

/** Remove query strings, hashes, share IDs, invite tokens, and course IDs. */
export function analyticsUrl(value: unknown): unknown {
	if (typeof value !== "string" || !value) return value;
	try {
		const url = new URL(value, "https://keating.invalid");
		url.pathname = analyticsPath(url.pathname);
		url.search = "";
		url.hash = "";
		return url.origin === "https://keating.invalid" ? url.pathname : url.toString();
	} catch {
		return value.split(/[?#]/, 1)[0];
	}
}

export function sanitizeAnalyticsProperties(properties: Properties): Properties {
	const sanitized: Properties = { ...properties };
	for (const key of PRIVATE_CONTENT_PROPERTIES) delete sanitized[key];

	for (const key of ["$current_url", "$referrer", "$pathname", "$prev_pageview_pathname"]) {
		if (key in sanitized) sanitized[key] = analyticsUrl(sanitized[key]);
	}

	return sanitized;
}

export function sanitizePostHogEvent(event: CaptureResult | null): CaptureResult | null {
	if (!event) return null;
	return {
		...event,
		properties: sanitizeAnalyticsProperties(event.properties ?? {}),
	};
}

export function sanitizeReplayRequest<T extends { name?: string }>(request: T): T {
	return {
		...request,
		...(request.name ? { name: String(analyticsUrl(request.name)) } : {}),
	};
}

